/* Noir Exposé scene: full logo reveal → fade to black → layered men, clouds and written ink. */
let noirRenderer=null;import('./noir-scene.js?v=depot-v17').then(({createNoirScene})=>{noirRenderer=createNoirScene();base._renderKey=''});
const cityBeforeNoir=renderOutdoor;renderOutdoor=function(ctx,seconds,d){if(seconds<d.noir){cityBeforeNoir(ctx,seconds,d);return}const age=seconds-d.noir,intro=fx.noirFadeStart+fx.noirFadeDuration+fx.noirBlackHold;if(age<intro){const cat=motionEase(age/Math.max(.1,fx.noirFadeStart+1),'smooth');renderCity(ctx,d.city+fx.cityDuration+age,d,{...fx,cityCatReveal:fx.cityCatReveal+(100-fx.cityCatReveal)*cat,cityCatRotation:cat*18,cityTurns:fx.cityTurns+cat*.12});ctx.globalAlpha=motionEase((age-fx.noirFadeStart)/fx.noirFadeDuration,'smooth');ctx.fillStyle='#000';ctx.fillRect(0,0,960,540);ctx.globalAlpha=1}else if(noirRenderer)noirRenderer(ctx,age,fx,sprites);else{ctx.fillStyle='#000';ctx.fillRect(0,0,960,540)}};
panels.noir={title:'Noir Exposé.',description:'The city fades out. Two rear-view cutouts, clouds and stroke-written words move at separate depths.',main:[['noirDuration','Scene duration (s)',25,80,.5,'Short','Long'],['noirReveal','Brightening & parallax time (s)',3,22,.2,'Fast','Slow'],['noirExposure','Scene brightness (%)',0,130,1,'Dark','Bright']],more:[['noirFadeStart','Start dimming (s)',0,12,.2,'Early','Late'],['noirFadeDuration','Dimming duration (s)',.5,10,.2,'Fast','Slow'],['noirBlackHold','Hold complete black (s)',0,5,.2,'Brief','Long'],['noirStartScale','People starting size',.6,2,.05,'Small','Close'],['noirEndScale','People ending size',.4,1.6,.05,'Small','Close'],['noirBackDepth','Background push',0,.6,.02,'Flat','Deep'],['noirCloudSpeed','Cloud drift',-30,30,1,'Left','Right'],['noirShiftStart','Sideways move starts (s)',0,40,.2,'Early','Late'],['noirShiftTime','Sideways move duration (s)',1,20,.2,'Fast','Slow'],['noirShift','People sideways travel (px)',-250,250,5,'Left','Right']]};
const noirTab=document.createElement('button');noirTab.dataset.stage='noir';noirTab.innerHTML='<span>12</span>Noir';stages.append(noirTab);let noirTextIndex=0;
function seekNoir(age){playing=false;t=(phaseTimes().noir+Math.max(0,Math.min(fx.noirDuration,age)))/settings.duration;document.querySelector('#play').textContent='▶';base._renderKey=''}
function renderNoirTextEditor(){const host=document.querySelector('#noirTextEditor');if(!host)return;noirTextIndex=Math.min(noirTextIndex,fx.noirTexts.length-1);const layer=fx.noirTexts[noirTextIndex];host.innerHTML='<label for="noirTime">Preview scene time (s)</label><input id="noirTime" type="number" value="18" min="0"><button class="pill wide" id="noirSeek">Go to time</button><label for="noirTextSelect">Written text layer</label><select id="noirTextSelect"></select><button class="pill wide" id="addNoirText">Add handwritten text</button><div id="noirTextFields"></div><button class="pill wide" id="noirMenReplace">Replace people cutout…</button><button class="pill wide" id="noirSkyReplace">Replace cloud / mountain image…</button>';const select=host.querySelector('#noirTextSelect');fx.noirTexts.forEach((l,i)=>{const o=document.createElement('option');o.value=i;o.textContent=l.text;select.append(o)});select.value=noirTextIndex;select.onchange=()=>{noirTextIndex=+select.value;renderNoirTextEditor()};host.querySelector('#noirSeek').onclick=()=>seekNoir(+host.querySelector('#noirTime').value);host.querySelector('#addNoirText').onclick=()=>{fx.noirTexts.push({id:'ink-'+Date.now(),text:'New words',x:160,y:260,size:65,start:10,duration:4,color:'#876878',style:'brush',depth:.4,rotation:0,blur:0});noirTextIndex=fx.noirTexts.length-1;saveEffects();renderNoirTextEditor()};host.querySelector('#noirMenReplace').onclick=()=>chooseAsset('mysteryMen');host.querySelector('#noirSkyReplace').onclick=()=>chooseAsset('mysterySky');if(!layer)return;
const fields=host.querySelector('#noirTextFields');fields.innerHTML='<label for="writtenWords">Words</label><input id="writtenWords" type="text" maxlength="80"><label for="writtenStyle">Pen style</label><select id="writtenStyle"><option value="brush">Noir Brush · pressure strokes</option><option value="ink">Noir Ink · fine strokes</option><option value="chalk">Noir Chalk · dry strokes</option></select><label for="writtenColor">Ink color</label><input id="writtenColor" type="color"><div class="directorGrid">'+[['x','Position X',0],['y','Position Y',0],['size','Size',0],['start','Writing starts (s)',0],['duration','Writing duration (s)',0],['rotation','Rotation (°)',0],['depth','Parallax depth',0],['blur','Text softness (px)',0],['whiteStart','White takeover starts (s)',18],['whiteDuration','White takeover duration (s)',4],['whiteGlyphStart','First white letter (0-based)',3],['whiteGlyphEnd','Last white letter (0-based)',6]].map(([id,label,fallback])=>`<label>${label}<input data-ink="${id}" type="number" step="${id==='depth'?.05:.2}" value="${layer[id]??fallback}"></label>`).join('')+'</div><label for="whiteMode">White takeover</label><select id="whiteMode"><option value="none">Off</option><option value="glyph-spread">Spread through whole letters</option><option value="silhouette">Where the men overlap</option><option value="wipe">Paint left → right</option><option value="full">Whole word</option></select><label for="whiteInkColor">Takeover color</label><input id="whiteInkColor" type="color"><button class="pill wide" id="removeNoirText">Remove text layer</button>';
fields.querySelector('#writtenWords').value=layer.text;fields.querySelector('#writtenStyle').value=layer.style;fields.querySelector('#writtenColor').value=layer.color;fields.querySelector('#whiteMode').value=layer.whiteMode||'none';fields.querySelector('#whiteInkColor').value=layer.whiteColor||'#ffffff';for(const [id,key]of [['writtenWords','text'],['writtenStyle','style'],['writtenColor','color'],['whiteInkColor','whiteColor']])fields.querySelector('#'+id).oninput=e=>{layer[key]=e.target.value;saveEffects()};fields.querySelectorAll('[data-ink]').forEach(el=>el.oninput=()=>{layer[el.dataset.ink]=+el.value;saveEffects()});fields.querySelector('#whiteMode').onchange=e=>{layer.whiteMode=e.target.value;if(e.target.value==='none')delete layer.whiteStart;else layer.whiteStart??=18;saveEffects()};fields.querySelector('#removeNoirText').onclick=()=>{fx.noirTexts.splice(noirTextIndex,1);saveEffects();renderNoirTextEditor()}}
const startBeforeNoir=startPart;startPart=function(key,adjusting=false){if(key==='noir'){if(chessEditing)setChessMode(false);if(!adjusting||!playing)t=phaseTimes().noir/settings.duration;playing=true;document.querySelector('#play').textContent='Ⅱ'}else startBeforeNoir(key,adjusting)};
const selectBeforeNoir=selectEffect;selectEffect=function(key,jump=true){selectBeforeNoir(key,jump);if(key==='noir'){const swap=controls.querySelector('#swapEffect');swap.previousElementSibling.style.display='none';swap.style.display='none';const box=document.createElement('details');box.className='fineTune';box.open=true;box.innerHTML='<summary>Handwritten text & cutouts</summary><div id="noirTextEditor"></div>';controls.querySelector('#watchEffect').after(box);renderNoirTextEditor()}};stages.querySelectorAll('button').forEach(b=>b.onclick=()=>selectEffect(b.dataset.stage));
const frameBeforeNoir=frame;frame=function(el,p){frameBeforeNoir(el,p);if(el===base&&p*settings.duration>=phaseTimes().noir)stages.querySelectorAll('button').forEach(b=>b.classList.toggle('playing',b.dataset.stage==='noir'))};const clickBeforeNoir=base.onclick;base.onclick=()=>{if(t*settings.duration>=phaseTimes().noir){selectEffect('noir',false);playing=false;document.querySelector('#play').textContent='▶'}else clickBeforeNoir()};
const noirCss=document.createElement('style');noirCss.textContent='#noirTextEditor input[type=text],#noirTextEditor input[type=number]{width:100%;background:#191c22;color:#e5e7ed;border:1px solid #3b4049;border-radius:5px;padding:8px}#noirTextEditor select{width:100%}';document.head.append(noirCss);syncDuration();
